// v1.5.0 — crawl first, personalize after (JS side).
//   * LOCKED REGRESSION: giyim / 10.000 TL / yurt içi / fiziki POS, işyeri BOŞ — over genuine crawler output
//     (web/fixtures/giyim-regression.v1.json, generated by tools/gen-giyim-fixture.py; Python test fails if stale)
//   * category-only Hangi Kart? is first-class; merchant-scope semantics when the merchant is empty
//   * manual category is authoritative; "Potansiyel" only for same-context adjustable thresholds
//   * Hangi Kart? sees owned cards only; unknown/unowned-card campaigns stay in the catalog (secondary sections)
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { recommend, evaluateCampaign, merchantMatch, merchantScopeClass, resolveMerchantInput, NETWORK_MERCHANT_WARNING } from './engine.js';
import { buildEligibilityContext, evaluateCampaignForCard, campaignTargetsCard } from './eligibility.js';
import { groupCampaignsByCard, catalogSecondary } from './campaign-browser.js';

const FIX = JSON.parse(readFileSync(new URL('./fixtures/giyim-regression.v1.json', import.meta.url), 'utf8'));
const NOW = new Date('2026-10-04T12:00:00+03:00');
const card = (code, bank, name, bankCode) => ({ cardProductId: code, bank, name, bankCode, active: true, segment: null });
const OWNED = [
  card('teb-infinite', 'TEB', 'TEB Özel Infinite', 'teb'),
  card('qnb-ms-private', 'QNB', 'Miles&Smiles QNB Private', 'qnb'),
  card('is-maximiles-black', 'İş Bankası', 'Maximiles Black', 'isbank'),
];
const CTX = buildEligibilityContext({ cards: OWNED, banks: ['teb', 'qnb', 'isbank'], attributes: {} });
const QUERY = { merchant: '', category: 'giyim', amount: 10000, locationScope: 'domestic', paymentChannel: 'physical', now: NOW, states: {}, eligibilityContext: CTX };
const byTitle = t => FIX.campaigns.find(c => c.title.includes(t));
const allEvals = r => [...(r.all || []), ...(r.potentials || []), ...(r.informational || []), ...(r.merchantConditional || []), ...(r.merchantSpecific || [])];

// ------------------------------------------------------------------ locked giyim regression
{
  const results = recommend({ cards: OWNED, campaigns: FIX.campaigns, ...QUERY });
  const of = code => results.find(r => r.card.cardProductId === code);

  // Hangi Kart? sees only owned cards (Wings campaigns exist in the catalog; no Wings card here)
  assert.deepEqual(results.map(r => r.card.cardProductId).sort(), OWNED.map(c => c.cardProductId).sort());
  assert.ok(FIX.campaigns.some(c => (c.cardProductIds || []).includes('akbank-wings-black')), 'unowned-card campaigns stay in the catalog');

  // TEB "Giyim Alışverişlerinize Toplam 1.200 TL Bonus!" (official terms, teb.com.tr/sizin-icin/giyim-alisveris/):
  // each single 3.000 TL+ transaction → 120 TL Bonus, max 1.200 TL, only at Bonus-member merchants.
  // Merchant empty → shown in the CONDITIONAL merchant section with the reward calculated; never the ranked winner.
  const teb = of('teb-infinite');
  const tebGiyim = teb.merchantConditional.find(e => e.campaign.title === 'Giyim Alışverişlerinize Toplam 1.200 TL Bonus!');
  assert.ok(tebGiyim, 'TEB giyim is in the conditional merchant section');
  assert.equal(tebGiyim.theoreticalReward, 120, 'per qualifying transaction (3.000 TL+ → 120 TL), never the 1.200 TL total and never 300');
  assert.equal(tebGiyim.campaign.periodCap, 1200);
  assert.equal(tebGiyim.merchantConditional, true);
  assert.ok(tebGiyim.inspection.warnings.includes(NETWORK_MERCHANT_WARNING));
  assert.equal(teb.best, null, 'a Bonus-member-network campaign is not a guaranteed ranked winner');
  assert.ok(!teb.all.some(e => e.campaign.title.includes('1.200 TL Bonus')));

  // QNB "Giyim ve Kozmetik Alışverişinize 2.000'e Varan Mil Hediye!" — per qualifying transaction, no 2 × 5.000 split
  const qnb = of('qnb-ms-private');
  assert.ok(qnb.best);
  assert.match(qnb.best.campaign.title, /Giyim ve Kozmetik Alışverişinize 2\.000/);
  assert.equal(qnb.best.theoreticalReward, 500, 'one 10.000 TL transaction = one qualifying transaction = 500 Mil');

  // No MercedesCard campaign appears as Maximiles Black (anywhere in its result)
  const maxi = of('is-maximiles-black');
  assert.ok(!allEvals(maxi).some(e => /MercedesCard/i.test(e.campaign.title)), 'MercedesCard never applies to Maximiles Black');
  assert.equal(maxi.best, null);

  // Hubs are never campaigns
  for (const hub of ['MercedesCard Kampanyaları', 'Giyim&Aksesuar Kampanyaları', 'Taksitlendirme&Erteleme']) {
    assert.ok(!FIX.campaigns.some(c => c.title === hub), `${hub} is not a campaign`);
  }
  // "TEB'den Yurt Dışı Harcamalarınıza %5 İndirim" is NOT potential for a domestic giyim query
  assert.ok(!allEvals(teb).some(e => /Yurt Dışı/.test(e.campaign.title)), 'international-only is a hard mismatch, never potential');
  // No "İşyeri adı girilmedi" hard block anywhere
  for (const r of results) for (const e of [...allEvals(r), ...(r.rejected || [])]) {
    assert.ok(!(e.inspection?.reasons || []).some(x => /İşyeri adı girilmedi/.test(x)));
  }
  console.log('locked giyim regression (10.000 TL · yurt içi · POS · işyeri boş): OK');
}

// ------------------------------------------------------------------ merchant-scope semantics (merchant empty)
{
  const base = { bank: 'TEB', bankCode: 'teb', status: 'active', categories: ['giyim'], cardProductIds: ['teb-infinite'], rulesComplete: true,
    rewardRule: { kind: 'percent', rate: 0.1, minSpend: 1000 }, transactionRules: {}, startDate: '2026-10-01', endDate: '2026-10-31',
    eligibilityResolution: { state: 'resolved', cardProductIds: ['teb-infinite'] } };
  const camps = [
    { ...base, id: 'cat', title: 'Giyim alışverişlerine %10', merchantScope: { kind: 'all' } },
    { ...base, id: 'net', title: 'Anlaşmalı mağazalarda %10', merchantScope: { kind: 'contains', values: ['A', 'B', 'C', 'D', 'E'], requiresBranchConfirmation: true } },
    { ...base, id: 'sel', title: "Seçili mağazalarda %10", merchantScope: { kind: 'restricted_unknown' } },
    { ...base, id: 'brand', title: "Index'te %10", merchantScope: { kind: 'contains', values: ['Index'] } },
    { ...base, id: 'exact', title: 'Tek mağaza %10', merchantScope: { kind: 'exact', values: ['Mağaza X'] } },
  ];
  assert.equal(merchantScopeClass(camps[0]), 'category');
  assert.equal(merchantScopeClass(camps[1]), 'network');
  assert.equal(merchantScopeClass(camps[2]), 'network');
  assert.equal(merchantScopeClass(camps[3]), 'brand');
  assert.equal(merchantScopeClass(camps[4]), 'exact');
  assert.equal(merchantMatch(camps[1], '').warning, NETWORK_MERCHANT_WARNING);
  const tc = OWNED[0];
  const [r] = recommend({ cards: [tc], campaigns: camps, ...QUERY });
  assert.equal(r.best.campaign.id, 'cat', 'category-wide campaign is calculated normally');
  assert.equal(r.best.theoreticalReward, 1000);
  assert.deepEqual(r.merchantConditional.map(e => e.campaign.id).sort(), ['net', 'sel'], 'network → conditional, not guaranteed');
  assert.ok(r.merchantConditional.every(e => e.conditional && e.inspection.warnings.includes(NETWORK_MERCHANT_WARNING)));
  assert.deepEqual(r.merchantSpecific.map(e => e.campaign.id).sort(), ['brand', 'exact'], 'brand/exact → "işyeri özel fırsatlar", no definite winner');
  assert.ok(!r.all.some(e => ['net', 'sel', 'brand', 'exact'].includes(e.campaign.id)));
  // With ONLY network/brand campaigns there is no definite winner at all
  const [r2] = recommend({ cards: [tc], campaigns: camps.slice(1), ...QUERY });
  assert.equal(r2.best, null);
  // When the merchant IS given, brand campaigns compute normally
  const [r3] = recommend({ cards: [tc], campaigns: camps, ...QUERY, merchant: 'Index' });
  assert.ok(r3.all.some(e => e.campaign.id === 'brand'));
  console.log('category-only Hangi Kart? merchant-scope semantics: OK');
}

// ------------------------------------------------------------------ manual category is authoritative
{
  const reg = resolveMerchantInput([], 'Migros', 'giyim');
  assert.equal(reg.effectiveCategory, 'giyim');
  assert.equal(resolveMerchantInput([], 'Migros', 'auto').effectiveCategory, 'market');
  assert.equal(resolveMerchantInput([], '', 'giyim').effectiveCategory, 'giyim');
  console.log('manual category authoritative: OK');
}

// ------------------------------------------------------------------ narrow "Potansiyel"
{
  const tc = OWNED[0];
  const mk = (id, extra) => ({ id, title: id, bank: 'TEB', status: 'active', categories: ['giyim'], cardProductIds: ['teb-infinite'], merchantScope: { kind: 'all' },
    rulesComplete: true, rewardRule: { kind: 'fixed', minSpend: 15000, reward: 500 }, transactionRules: {}, ...extra });
  const camps = [
    mk('min-gap', {}),                                                            // same context, adjustable amount → potential
    mk('intl', { transactionRules: { location: 'international' } }),              // hard
    mk('online', { transactionRules: { allowedChannels: ['online'] } }),          // hard
    mk('other-cat', { categories: ['market'] }),                                 // hard
    mk('unowned', { cardProductIds: ['akbank-wings-black'] }),                    // card not owned → hard
  ];
  const [r] = recommend({ cards: [tc], campaigns: camps, ...QUERY });
  assert.deepEqual(r.potentials.map(e => e.campaign.id), ['min-gap']);
  const intl = evaluateCampaign({ campaign: camps[1], card: tc, ...QUERY });
  assert.equal(intl.potential, false);
  assert.ok(intl.hardBlockers.some(b => b.code === 'location'));
  console.log('narrow potential (location/channel/category/card are hard): OK');
}

// ------------------------------------------------------------------ unresolved eligibility is never applicable
{
  const c = { id: 'u', title: 'u', status: 'active', cardProductIds: ['teb-infinite'], categories: ['giyim'], merchantScope: { kind: 'all' },
    rewardRule: { kind: 'fixed', minSpend: 0, reward: 1 }, rulesComplete: true, eligibilityResolution: { state: 'needs_review', cardProductIds: [] } };
  assert.equal(evaluateCampaignForCard(c, OWNED[0], CTX).eligible, false);
  assert.equal(campaignTargetsCard(c, OWNED[0], CTX), false);
  console.log('unresolved/needs_review fail closed: OK');
}

// ------------------------------------------------------------------ Kampanyalar default = definitely applicable only
{
  const groups = groupCampaignsByCard({ campaigns: FIX.campaigns, cards: OWNED, category: 'all', now: NOW, eligibilityContext: CTX });
  const teb = groups.find(g => g.card.cardProductId === 'teb-infinite');
  assert.ok(teb.campaigns.some(c => c.title === 'Giyim Alışverişlerinize Toplam 1.200 TL Bonus!'));
  for (const g of groups) assert.ok(g.campaigns.every(c => c.rulesComplete !== false && !c.rewardVariantUnresolved));
  const maxi = groups.find(g => g.card.cardProductId === 'is-maximiles-black');
  assert.equal(maxi.campaigns.length + maxi.informational.length, 0, 'no MercedesCard / unknown-card campaign under Maximiles Black');
  const sec = catalogSecondary({ campaigns: FIX.campaigns, cards: OWNED, category: 'all', now: NOW, eligibilityContext: CTX });
  assert.ok(sec.unresolved.some(c => /Kitap/.test(c.title)), 'unknown-card campaign stays visible in a secondary section');
  assert.ok(sec.otherCards.some(c => /MercedesCard/.test(c.title)), 'MercedesCard stays in the global catalog (other cards)');
  assert.ok(!sec.unresolved.concat(sec.otherCards).some(c => c.bankCode === 'akbank'), 'only the user\'s banks');
  console.log('Kampanyalar default applicable-only + secondary sections: OK');
}

// ------------------------------------------------------------------ family/program scope (not "the one known product")
{
  const { BUNDLED_PROFILE_CATALOG: CAT } = await import('./profile-catalog.js');
  const tebC = byTitle('Giyim Alışverişlerinize Toplam 1.200 TL Bonus!');
  const qnbC = byTitle("Giyim ve Kozmetik Alışverişinize 2.000");
  const snapshot = JSON.stringify([tebC, qnbC]);
  // The canonical campaign rule is family-level, never the current product list
  assert.deepEqual(tebC.eligibilityRule, { payWith: { families: ['teb-bonus-individual-credit'] } });
  assert.deepEqual(qnbC.eligibilityRule, { payWith: { families: ['miles-smiles-qnb'] } });
  assert.deepEqual(tebC.cardFamilies, ['teb-bonus-individual-credit']); assert.deepEqual(tebC.cardProductIds, []);
  assert.deepEqual(qnbC.cardFamilies, ['miles-smiles-qnb']); assert.deepEqual(qnbC.cardProductIds, []);
  assert.equal(tebC.eligibilityResolution.state, 'partial');
  assert.equal(qnbC.eligibilityResolution.state, 'partial');

  // Master data with FUTURE products: a second TEB Bonus card, a non-Bonus TEB card,
  // a second Miles&Smiles QNB card and an ordinary QNB card. Only membership changes; campaign records do not.
  const future = JSON.parse(JSON.stringify(CAT));
  future.cardProducts.push(
    { code: 'teb-bonus-platinum-x', bankCode: 'teb', name: 'TEB Bonus Platinum (test)', family: 'teb-bonus' },
    { code: 'teb-nonbonus-x', bankCode: 'teb', name: 'TEB non-Bonus (test)', family: 'teb-other' },
    { code: 'qnb-ms-classic-x', bankCode: 'qnb', name: 'Miles&Smiles QNB Classic (test)', family: 'miles-smiles-qnb' },
    { code: 'qnb-ordinary-x', bankCode: 'qnb', name: 'QNB Card (test)', family: 'qnb-card' });
  const fam = code => future.cardFamilies.find(f => f.code === code);
  fam('teb-bonus-individual-credit').members.push('teb-bonus-platinum-x');
  fam('teb-individual-credit').members.push('teb-bonus-platinum-x', 'teb-nonbonus-x');   // non-Bonus TEB card is NOT Bonus-family
  fam('miles-smiles-qnb').members.push('qnb-ms-classic-x');
  fam('qnb-individual-credit').members.push('qnb-ms-classic-x', 'qnb-ordinary-x');      // ordinary QNB card is NOT M&S family

  const cardsAll = [
    card('teb-infinite', 'TEB', 'TEB Özel Infinite', 'teb'), card('teb-bonus-platinum-x', 'TEB', 'Bonus X', 'teb'), card('teb-nonbonus-x', 'TEB', 'Non-Bonus X', 'teb'),
    card('qnb-ms-private', 'QNB', 'M&S Private', 'qnb'), card('qnb-ms-classic-x', 'QNB', 'M&S Classic X', 'qnb'), card('qnb-ordinary-x', 'QNB', 'QNB Card X', 'qnb'),
  ];
  const ctxNow = buildEligibilityContext({ cards: OWNED, banks: ['teb', 'qnb', 'isbank'], attributes: {}, catalog: CAT });
  const ctxFuture = buildEligibilityContext({ cards: cardsAll, banks: ['teb', 'qnb'], attributes: {}, catalog: future });
  const ok = (c, code, cx) => evaluateCampaignForCard(c, cardsAll.find(x => x.cardProductId === code) || OWNED.find(x => x.cardProductId === code), cx).eligible;

  assert.equal(ok(tebC, 'teb-infinite', ctxNow), true, 'TEB Infinite currently matches the TEB Bonus-family campaign');
  assert.equal(ok(qnbC, 'qnb-ms-private', ctxNow), true, 'M&S QNB Private currently matches the M&S QNB-family campaign');
  assert.equal(ok(tebC, 'teb-bonus-platinum-x', ctxFuture), true, 'a future second TEB Bonus card matches without changing the campaign');
  assert.equal(ok(tebC, 'teb-infinite', ctxFuture), true);
  assert.equal(ok(tebC, 'teb-nonbonus-x', ctxFuture), false, 'a non-Bonus TEB card does not match');
  assert.equal(ok(qnbC, 'qnb-ms-classic-x', ctxFuture), true, 'another M&S QNB product matches without changing the campaign');
  assert.equal(ok(qnbC, 'qnb-ordinary-x', ctxFuture), false, 'an ordinary QNB card does not match');
  assert.equal(campaignTargetsCard(tebC, cardsAll[2], ctxFuture), false);
  // End to end through Hangi Kart? with the future catalog
  const rec = recommend({ cards: cardsAll, campaigns: FIX.campaigns, ...QUERY, eligibilityContext: ctxFuture });
  const condFor = code => (rec.find(r => r.card.cardProductId === code).merchantConditional || []).map(e => e.campaign.title);
  assert.ok(condFor('teb-bonus-platinum-x').includes('Giyim Alışverişlerinize Toplam 1.200 TL Bonus!'));
  assert.ok(!condFor('teb-nonbonus-x').includes('Giyim Alışverişlerinize Toplam 1.200 TL Bonus!'));
  const bestTitle = code => rec.find(r => r.card.cardProductId === code).best?.campaign.title || '';
  assert.match(bestTitle('qnb-ms-classic-x'), /Giyim ve Kozmetik Alışverişinize 2\.000/);
  assert.doesNotMatch(bestTitle('qnb-ordinary-x'), /Giyim ve Kozmetik/);
  // Records were not rewritten by evaluation
  assert.equal(JSON.stringify([tebC, qnbC]), snapshot, 'campaign records stay family-scoped and unchanged');
  console.log('family/program scope (TEB Bonus family, Miles&Smiles QNB family, future members): OK');
}
